<?php namespace Workspace;
$today=gmdate('Y-m-d');$fmt=fn($v)=>money((int)$v);$rateFmt=fn($v)=>intdiv((int)$v,BANK_SCALE).'.'.str_pad((string)((int)$v%BANK_SCALE),6,'0',STR_PAD_LEFT);$base=$statement?['statement'=>$statement['id']]:($account?['account'=>$account['id']]:[]);
?>
<section class="panel"><h2>Банковские счета</h2><p>Импорт наблюдений из банка не создаёт кассовых проводок. Сопоставляйте с фактически проведёнными записями кассы или <a href="<?= h(url('invoices')) ?>">оплатами счетов</a>.</p>
<form method="get"><input type="hidden" name="p" value="bank"><label>Банковский счёт<select name="account"><?php foreach($accounts as $a): ?><option value="<?= h($a['id']) ?>" <?= $account&&(int)$account['id']===(int)$a['id']?'selected':'' ?>><?= h($a['name'].' · '.$a['entity_name'].' · '.$a['currency']) ?></option><?php endforeach ?></select></label><button>Открыть</button></form>
<?php if($writable&&$user['role']==='owner'&&$entities): ?><details><summary>Добавить банковский счёт</summary><form method="post"><?php formFields('bank.account') ?><label>Юрлицо<select name="entity_id"><?php selectOptions(array_column($entities,'name','id')) ?></select></label><label>Название<input name="name" maxlength="180" required></label><label>Идентификатор счёта (IBAN или внутренний ID)<input name="account_ref" maxlength="180" required></label><label>Валюта<select name="currency"><?php selectOptions(array_combine(CURRENCIES,CURRENCIES)) ?></select></label><button>Добавить</button></form></details><?php endif ?>
<?php if(!$entities): ?><p>Сначала создайте юридическое лицо в разделе «Счета».</p><?php endif ?></section>
<?php if($account): ?><section class="panel"><h2>Выписки · <?= h($account['name'].' · '.$account['currency']) ?></h2><p>Счёт: <?= h($account['account_ref']) ?></p>
<?php if($writable): ?><details><summary>Импорт новой выписки</summary><p>UTF-8 CSV, максимум 1 МиБ / 5000 строк. Сумма — фактическое изменение банковского остатка со знаком, включая комиссию; комиссия — неотрицательная сумма. Для выписки без движений передайте только заголовок. Даты следующих выписок и начальные остатки должны продолжать предыдущую.</p><pre>reference,date,amount,fee,description</pre><form method="post" enctype="multipart/form-data"><?php formFields('bank.import') ?><input type="hidden" name="account_id" value="<?= h($account['id']) ?>"><label>Начало<input name="starts_on" type="date" max="<?= h($today) ?>" required></label><label>Конец<input name="ends_on" type="date" max="<?= h($today) ?>" required></label><label>Начальный остаток<input name="opening" required></label><label>Конечный остаток<input name="closing" required></label><label>CSV-файл<input type="file" name="statement_file" accept=".csv,text/csv"></label><label>Или текст CSV<textarea name="csv" rows="6" placeholder="reference,date,amount,fee,description"></textarea></label><button>Импортировать и проверить остатки</button></form></details><?php endif ?>
<?php if($statements): ?><form method="get"><input type="hidden" name="p" value="bank"><input type="hidden" name="account" value="<?= h($account['id']) ?>"><label>Выписка<select name="statement"><?php foreach($statements as $s): ?><option value="<?= h($s['id']) ?>" <?= $statement&&(int)$statement['id']===(int)$s['id']?'selected':'' ?>><?= h('#'.$s['id'].' · '.$s['starts_on'].' — '.$s['ends_on']) ?></option><?php endforeach ?></select></label><button>Открыть выписку</button></form><?php endif ?></section><?php endif ?>
<section class="panel"><h2>Курсы на дату</h2><p>Курс: единиц валюты банка за одну единицу валюты кассы. Указывайте подтверждённый источник; курс неизменяем после регистрации.</p>
<?php if($writable): ?><details><summary>Зарегистрировать курс</summary><form method="post"><?php formFields('bank.rate') ?><label>Дата<input type="date" name="rate_on" value="<?= h($today) ?>" max="<?= h($today) ?>" required></label><label>Валюта кассы<select name="base_currency"><?php selectOptions(array_combine(CURRENCIES,CURRENCIES),'USD') ?></select></label><label>Валюта банка<select name="quote_currency"><?php selectOptions(array_combine(CURRENCIES,CURRENCIES),'EUR') ?></select></label><label>Курс<input name="rate" placeholder="0.925000" required></label><label>Источник / подтверждение<input name="source" maxlength="500" required></label><button>Сохранить курс</button></form></details><?php endif ?>
<div class="tablewrap"><table><thead><tr><th>ID / дата</th><th>Пара</th><th>Курс</th><th>Источник</th></tr></thead><tbody><?php foreach($rates as $r): ?><tr><td>#<?= h($r['id'].' · '.$r['rate_on']) ?></td><td><?= h($r['base_currency'].' → '.$r['quote_currency']) ?></td><td><?= h($rateFmt($r['rate_scaled'])) ?></td><td><?= h($r['source']) ?></td></tr><?php endforeach ?></tbody></table></div></section>
<?php if($statement&&$result): $report=$result['report']; ?>
<section class="panel"><h2>Сверка #<?= h($statement['id']) ?> · <?= h($statement['currency']) ?></h2><p><?= h($statement['starts_on'].' — '.$statement['ends_on']) ?> · <?= $report['ok']?'Все компоненты сопоставлены; остатки сходятся.':'Есть несопоставленные операции или расхождения.' ?></p>
<div class="tablewrap"><table><tbody><?php foreach(['Начало'=>(int)$statement['opening_minor'],'Движение банка'=>$report['net'],'Конечный расчёт'=>$report['calculated_closing'],'Конец по выписке'=>(int)$statement['closing_minor'],'Разница остатков'=>$report['balance_difference'],'Комиссии (включены в движение)'=>$report['fees'],'Эквивалент сопоставленной кассы'=>$report['equivalent'],'Объяснённое валютное расхождение'=>$report['fx_variance'],'Несопоставленное движение'=>$report['unmatched_net'],'Необъяснённая разница'=>$report['unexplained']] as $k=>$v): ?><tr><th><?= h($k) ?></th><td><?= h($fmt($v)) ?></td></tr><?php endforeach ?></tbody></table></div>
<p>Строк: <?= h($report['rows']) ?> · ожидают сверки: <?= h($report['unmatched']) ?> · недействительных сопоставлений: <?= h($report['invalid']) ?>. Валютное расхождение является объяснением в банковской сверке, не бухгалтерской проводкой.</p>
<?php if($writable): ?><form method="post"><?php formFields('bank.reconcile') ?><input type="hidden" name="id" value="<?= h($statement['id']) ?>"><button>Сохранить результат повторной сверки</button></form><?php endif ?>
<h3>История проверок</h3><div class="tablewrap"><table><thead><tr><th>Время / автор</th><th>Результат</th><th>Контроль</th></tr></thead><tbody><?php foreach($history as $r): $saved=json_decode($r['report'],true,512,JSON_THROW_ON_ERROR); ?><tr><td><?= h(gmdate('Y-m-d H:i:s',(int)$r['created_at']).' UTC · #'.$r['actor_id']) ?></td><td><?= (int)$r['ok']?'Сошлось':'Не сошлось' ?> · остаток <?= h($fmt($saved['balance_difference'])) ?> · несопоставлено <?= h($saved['unmatched']) ?> · FX <?= h($fmt($saved['fx_variance'])) ?></td><td><?= hash_equals($r['digest'],$result['digest'])?'Текущие данные':'Исторический снимок' ?><br><code><?= h($r['digest']) ?></code></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="panel"><h2>Очередь банковских операций</h2><p><?php foreach(['unmatched'=>'Не распознаны / требуют сверки','matched'=>'Сопоставленные','all'=>'Все'] as $k=>$label): ?><a href="<?= h(url('bank',$base+['filter'=>$k])) ?>"><?= h($label) ?><?= $filter===$k?' ✓':'' ?></a> · <?php endforeach ?></p><div class="tablewrap"><table><thead><tr><th>Дата / ID</th><th>Назначение</th><th>Нетто</th><th>Комиссия</th><th>Состояние</th></tr></thead><tbody><?php foreach($visible as $r): ?><tr><td><?= h($r['booked_on']) ?><br><a href="<?= h(url('bank',$base+['row'=>$r['id'],'filter'=>$filter])) ?>"><?= h($r['external_ref']) ?></a></td><td><?= h($r['description']) ?></td><td><?= h($fmt($r['net_minor'])) ?></td><td><?= h($fmt($r['fee_minor'])) ?></td><td><?= h(['matched'=>'Сопоставлена','unmatched'=>'Не распознана','invalid'=>'Требует повторной сверки'][$r['state']]) ?></td></tr><?php endforeach ?></tbody></table></div><?php if($next): ?><a href="<?= h(url('bank',$base+['filter'=>$filter,'after'=>$next])) ?>">Следующие операции</a><?php endif ?></section>
<?php if($selected): $principal=(int)$selected['net_minor']+(int)$selected['fee_minor']; ?><section class="panel"><h2>Операция #<?= h($selected['id']) ?> · <?= h($selected['external_ref']) ?></h2><p><?= h($selected['booked_on'].' · '.$selected['description']) ?></p><p>Основная сумма <?= h($fmt($principal)) ?> · комиссия <?= h($fmt($selected['fee_minor'])) ?> · валюта <?= h($selected['currency']) ?>.</p>
<?php foreach($selected['allocations'] as $k=>$a): $cash=$a['cash']; ?><p><?= $k==='principal'?'Основная сумма':'Комиссия' ?>: кассовая запись #<?= h($cash['id']) ?>, <?= h($fmt($cash['amount_minor']).' '.$cash['currency']) ?><?php if($cash['invoice_id']): ?> · <a href="<?= h(url('invoices',['project'=>$cash['project_id'],'id'=>$cash['invoice_id']])) ?>">Счёт #<?= h($cash['invoice_id']) ?></a><?php endif ?> · эквивалент <?= h($fmt($a['equivalent_minor'])) ?> · FX <?= h($fmt($a['variance_minor'])) ?><?php if($a['rate']): ?> · курс <?= h($rateFmt($a['rate']['rate_scaled'])) ?> (<?= h($a['rate']['source']) ?>)<?php endif ?> · <?= h($a['explanation']) ?></p><?php endforeach ?>
<?php if($writable&&$selected['has_allocations']): ?><form method="post"><?php formFields('bank.unmatch') ?><input type="hidden" name="id" value="<?= h($selected['id']) ?>"><input type="hidden" name="version" value="<?= h($selected['version']) ?>"><label>Причина отмены<input name="explanation" maxlength="500" required></label><button>Снять сопоставление</button></form>
<?php elseif($writable): ?><p>Кандидаты — проведённые кассовые записи за эту дату. При необходимости сначала зарегистрируйте оплату или возврат в счёте либо комиссию как расход в <a href="<?= h(url('finance')) ?>">кассовой книге</a>. Для оплаты и комиссии используйте разные записи одного проекта.</p>
<div class="tablewrap"><table><thead><tr><th>Касса ID</th><th>Проект / счёт</th><th>Сумма</th><th>Назначение</th></tr></thead><tbody><?php foreach($candidates as $c): ?><tr><td>#<?= h($c['id']) ?></td><td><?= h($c['title']) ?><?php if($c['invoice_id']): ?> · <a href="<?= h(url('invoices',['project'=>$c['project_id'],'id'=>$c['invoice_id']])) ?>">Счёт #<?= h($c['invoice_id']) ?></a> · <?= h($c['invoice_reference']) ?><?php endif ?></td><td><?= h(($c['direction']==='income'?'+':'−').$fmt($c['amount_minor']).' '.$c['currency']) ?></td><td><?= h($c['memo']) ?></td></tr><?php endforeach ?></tbody></table></div>
<form method="post"><?php formFields('bank.match') ?><input type="hidden" name="id" value="<?= h($selected['id']) ?>"><input type="hidden" name="version" value="<?= h($selected['version']) ?>"><?php if($principal!==0): ?><label>ID основной кассовой записи<input name="principal_id" type="number" min="1" required></label><?php endif ?><?php if((int)$selected['fee_minor']>0): ?><label>ID кассового расхода комиссии<input name="fee_id" type="number" min="1" required></label><?php endif ?><?php if($principal!==0): ?><label>Курс для разновалютной операции<select name="rate_id"><option value="">Одинаковая валюта (без курса)</option><?php foreach($rowRates as $r): ?><option value="<?= h($r['id']) ?>"><?= h($r['base_currency'].' → '.$r['quote_currency'].' · '.$rateFmt($r['rate_scaled'])) ?></option><?php endforeach ?></select></label><?php endif ?><label>Обоснование (обязательно при валютном расхождении)<input name="explanation" maxlength="500"></label><button>Сопоставить</button></form><?php endif ?>
<h3>История сопоставления</h3><?php foreach($matchHistory as $e): ?><details><summary><?= h($e['event'].' · '.gmdate('Y-m-d H:i:s',(int)$e['created_at']).' UTC · #'.$e['actor_id']) ?></summary><p><?= h($e['note']) ?></p><?php foreach(json_decode($e['evidence'],true,512,JSON_THROW_ON_ERROR) as $a): ?><p><?= h($a['component'].' · касса #'.$a['cash_id'].' · эквивалент '.$fmt($a['equivalent_minor']).' · FX '.$fmt($a['variance_minor']).' · курс #'.($a['rate_id']??'—')) ?></p><?php endforeach ?></details><?php endforeach ?></section><?php endif ?><?php endif ?>
